 if(actionType==='accessory'){actionValue=String((Number(actionValue)+(key==='ArrowDown'?1:3))%4);return 'accessory '+['No accessory','Headset','Handsfree','TTY'][Number(actionValue)]}
 if(actionType==='callergroup'&&phoneState.contacts.length){actionValue=String((Number(actionValue)+(key==='ArrowDown'?1:-1)+phoneState.contacts.length)%phoneState.contacts.length);return 'caller group contact '+phoneState.contacts[Number(actionValue)].name}
 if(actionType==='speeddial'&&phoneState.contacts.length){actionValue=String((Number(actionValue)+(key==='ArrowDown'?1:-1)+phoneState.contacts.length)%phoneState.contacts.length);return 'speed dial contact '+phoneState.contacts[Number(actionValue)].name}
 if(actionType==='networkmode'){actionValue=String((Number(actionValue)+(key==='ArrowDown'?1:2))%3);return 'network mode '+['Dual mode','GSM','3G'][Number(actionValue)]}
 if(actionType==='language'){actionValue=String((Number(actionValue)+(key==='ArrowDown'?1:3))%4);return 'language '+['English','French','German','Spanish'][Number(actionValue)]}
 if(actionType==='securitylevel'){actionValue=String((Number(actionValue)+(key==='ArrowDown'?1:2))%3);return 'security level '+['None','Memory','Phone'][Number(actionValue)]}
 if(actionType==='videoquality'){actionValue=String((Number(actionValue)+(key==='ArrowDown'?1:2))%3);return 'video quality '+['Basic','Normal','High'][Number(actionValue)]}
 if(actionType==='videolength'){actionValue=String((Number(actionValue)+(key==='ArrowDown'?1:2))%3);return 'video length '+['30 seconds','5 minutes','Maximum'][Number(actionValue)]}
 if(actionType==='cameratimer'){actionValue=String((Number(actionValue)+(key==='ArrowDown'?1:2))%3);return 'camera timer '+['Off','3 seconds','10 seconds'][Number(actionValue)]}
 if(actionType==='cameraeffect'){actionValue=String((Number(actionValue)+(key==='ArrowDown'?1:3))%4);return 'camera effect '+['Normal','Greyscale','Sepia','Negative'][Number(actionValue)]}
 if(actionType==='cameraquality'){actionValue=String((Number(actionValue)+(key==='ArrowDown'?1:2))%3);return 'camera quality '+['Basic','Normal','High'][Number(actionValue)]}
 if(actionType==='radio'){let n=Math.round((Number(actionValue)+(key==='ArrowDown'?-0.1:0.1))*10)/10;if(n<87.5)n=108;if(n>108)n=87.5;actionValue=n.toFixed(1);return 'radio frequency '+actionValue}
 if(actionType==='equaliser'){actionValue=String((Number(actionValue)+(key==='ArrowDown'?1:3))%4);return 'equaliser '+['Normal','Pop','Rock','Jazz'][Number(actionValue)]}
 if(actionType==='lights'){actionValue=String(Math.max(1,Math.min(5,Number(actionValue)-step)));return 'display light '+actionValue}
 if(actionType==='wallpaper'){actionValue=String((Number(actionValue)-step+3)%3);return 'wallpaper '+['Theme default','Analog clock','Menu background'][Number(actionValue)]}
 if(actionType==='fontcolour'){actionValue=String((Number(actionValue)-step+4)%4);return 'font colour '+['Automatic','White','Black','Blue'][Number(actionValue)]}
 if(actionType==='clockoffset'){actionValue=String(Math.max(-720,Math.min(720,Number(actionValue)+(key==='ArrowDown'?-5:5))));return 'clock offset '+actionValue+' minutes'}
 if(actionType==='timezone'){actionValue=String((Number(actionValue)+(key==='ArrowDown'?1:3))%4);return 'time zone '+['Local','UTC','UTC+1','UTC-5'][Number(actionValue)]}
 if(actionType==='dateformat'){actionValue=String((Number(actionValue)+(key==='ArrowDown'?1:2))%3);return 'date format '+['DMY','MDY','YMD'][Number(actionValue)]}
 if(actionType==='timeformat'){actionValue=actionValue==='1'?'0':'1';return 'time format '+(actionValue==='1'?'24-hour':'12-hour')}
 if(actionType==='gotodate'){actionValue=String(Number(actionValue||0)+step);return 'calendar date offset '+actionValue}
 if(actionType==='calendar'){let [offset='0',body='']=actionValue.split('\t');if(key==='ArrowLeft'||key==='ArrowRight'){actionStatus=actionStatus==='date'?'body':'date';textKey='';return 'calendar field '+actionStatus}if(actionStatus==='date')offset=String(Number(offset||0)+step);actionValue=offset+'\t'+body;return 'calendar day offset '+offset}
 if(actionType==='countdown'&&!countdownEndAt){countdownRemaining=Math.max(60,countdownRemaining-step*60);return 'countdown '+countdownText()}
 if(actionType==='alarm'){
  let h=Number(actionValue.slice(0,2)),m=Number(actionValue.slice(3));
  if(key==='ArrowUp')h=(h+1)%24;if(key==='ArrowDown')h=(h+23)%24;
  if(key==='ArrowRight')m=(m+5)%60;if(key==='ArrowLeft')m=(m+55)%60;
  actionValue=String(h).padStart(2,'0')+':'+String(m).padStart(2,'0');return 'alarm time '+actionValue
 }
 if(actionType==='editcalendar'){let idx=actionStatus.split(':')[1],[date,body]=actionValue.split('\t');if(key==='ArrowLeft'||key==='ArrowRight'){actionStatus=(actionStatus.startsWith('date:')?'body:':'date:')+idx;textKey='';return 'calendar edit field '+actionStatus.split(':')[0]}if(actionStatus.startsWith('date:')){let d=new Date(date+'T12:00:00');d.setDate(d.getDate()+step);date=d.toISOString().slice(0,10);actionValue=date+'\t'+body}return 'calendar edit date '+date}
 if(actionType==='editdraft'){let i=actionStatus.split(':')[1];actionStatus=(actionStatus.startsWith('to:')?'body:':'to:')+i;textKey='';return 'draft edit field '+actionStatus.split(':')[0]}
