 if(actionType==='messagecentre'){phoneState.messageCentre=actionValue;return finishAction('saved message centre locally')}
 if(actionType==='charactersupport'){phoneState.characterSupport=['Full','Reduced'][Number(actionValue)];return finishAction('saved character support '+phoneState.characterSupport)}
 if(actionType==='shortcut'){let v=['Organiser','Names','Calendar','Notes','Messages'][Number(actionValue)];phoneState[actionStatus==='left'?'shortcutLeft':'shortcutRight']=v;return finishAction('saved '+actionStatus+' idle shortcut '+v)}
 if(actionType==='usbmode'){phoneState.usbMode=['Ask on connection','PC Suite','Mass storage'][Number(actionValue)];return finishAction('saved USB mode '+phoneState.usbMode)}
 if(actionType==='packetdata'){phoneState.packetData=['When needed','Always online','Off'][Number(actionValue)];return finishAction('saved packet data preference '+phoneState.packetData)}
 if(actionType==='accessory'){phoneState.accessory=['No accessory','Headset','Handsfree','TTY'][Number(actionValue)];return finishAction('saved default accessory '+phoneState.accessory)}
 if(actionType==='callergroup'){if(phoneState.contacts.length){if(actionStatus)phoneState.contacts[Number(actionValue)].group=actionStatus;else delete phoneState.contacts[Number(actionValue)].group}return finishAction(actionStatus?'assigned caller group '+actionStatus:'removed caller group')}
 if(actionType==='speeddial'){if(phoneState.contacts.length)phoneState.speedDials[actionStatus]=phoneState.contacts[Number(actionValue)].number;return finishAction('assigned speed dial '+actionStatus)}
 if(actionType==='networkmode'){phoneState.networkMode=['Dual mode','GSM','3G'][Number(actionValue)];return finishAction('saved network mode '+phoneState.networkMode)}
