 if(actionType==='securitylevel'){phoneState.securityLevel=['None','Memory','Phone'][Number(actionValue)];return finishAction('saved security level '+phoneState.securityLevel)}
 if(actionType==='videoquality'){phoneState.videoQuality=['Basic','Normal','High'][Number(actionValue)];return finishAction('saved video quality '+phoneState.videoQuality)}
 if(actionType==='videolength'){phoneState.videoLength=['30 seconds','5 minutes','Maximum'][Number(actionValue)];return finishAction('saved video length '+phoneState.videoLength)}
 if(actionType==='cameratimer'){phoneState.cameraTimer=['Off','3 seconds','10 seconds'][Number(actionValue)];return finishAction('saved camera timer '+phoneState.cameraTimer)}
 if(actionType==='cameraeffect'){phoneState.cameraEffect=['Normal','Greyscale','Sepia','Negative'][Number(actionValue)];return finishAction('saved camera effect '+phoneState.cameraEffect)}
 if(actionType==='cameraquality'){phoneState.cameraQuality=['Basic','Normal','High'][Number(actionValue)];return finishAction('saved camera quality '+phoneState.cameraQuality)}
 if(actionType==='radio'){phoneState.radioFrequency=actionValue;phoneState.radioOn=true;return finishAction('saved radio frequency '+phoneState.radioFrequency)}
 if(actionType==='localbackup'){if(actionStatus==='create'){let data=JSON.parse(JSON.stringify(phoneState));delete data.localBackup;phoneState.localBackup={createdAt:new Date().toISOString(),data};return finishAction('created local phone backup')}if(actionStatus==='restore'&&phoneState.localBackup){let backup=phoneState.localBackup;phoneState=Object.assign({},phoneDefaults,JSON.parse(JSON.stringify(backup.data)),{localBackup:backup});menuMode=phoneState.menuMode;applyTheme(phoneState.theme);applyFontColour(phoneState.fontColour);applyLightLevel(phoneState.lightLevel);applyWallpaper(phoneState.wallpaper);return finishAction('restored local phone backup')}if(actionStatus==='clear'){phoneState.localBackup=null;return finishAction('cleared local phone backup')}return finishAction('no local backup available')}
